"use client";
import { useActionFocus } from "@/lib/takt-focus";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { FileText, Check, ShieldCheck, Undo2, X } from "lucide-react";
import { panel, action as primary, secondary } from "@/lib/takt-surface";
export function ToolApproval({
  className,
  action = "Прочитать файл?",
  resource = "project/brief.md",
  onDecision,
}: {
  className?: string;
  action?: string;
  resource?: string;
  onDecision?: (allowed: boolean) => void;
}) {
  const { root, focusAfterRender } = useActionFocus<HTMLElement>();
  const [decision, setDecision] = useState<boolean | null>(null);
  function respond(value: boolean) {
    focusAfterRender("[data-reset]");
    setDecision(value);
    onDecision?.(value);
  }
  return (
    <section ref={root} className={cn(panel + " grid w-64 gap-3", className)}>
      <header className="flex items-center gap-2">
        <ShieldCheck size={17} />
        <strong>{action}</strong>
      </header>
      <code
        title={resource}
        className="flex items-center gap-2 overflow-hidden rounded-lg border bg-muted/50 px-3 py-2.5 font-mono text-xs"
      >
        <FileText size={14} />
        <span className="truncate">{resource}</span>
      </code>
      {decision === null ? (
        <div className="flex gap-1.5">
          <button
            type="button"
            className={secondary + " flex-1"}
            onClick={() => respond(false)}
          >
            Отклонить
          </button>
          <button
            type="button"
            className={primary + " flex-1 text-xs"}
            onClick={() => respond(true)}
          >
            Разрешить
          </button>
        </div>
      ) : (
        <div
          className="flex min-h-10 items-center gap-2 rounded-xl bg-muted px-2.5 text-xs font-medium motion-safe:animate-in motion-safe:slide-in-from-bottom-1"
          role="status"
        >
          {decision ? (
            <Check size={15} className="text-emerald-600" />
          ) : (
            <X size={15} className="text-rose-600" />
          )}{" "}
          {decision ? "Разрешено" : "Отклонено"}
          <button
            type="button"
            className="ml-auto rounded p-1.5"
            aria-label="Сброс"
            data-reset
            onClick={() => {
              focusAfterRender("button");
              setDecision(null);
            }}
          >
            <Undo2 size={14} />
          </button>
        </div>
      )}
    </section>
  );
}

"use client";

import { useLayoutEffect, useRef } from "react";

// Only move focus for a requested action that replaces the focused control.
export function useActionFocus<T extends HTMLElement>() {
  const root = useRef<T>(null);
  const pending = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (pending.current) {
      root.current
        ?.querySelector<HTMLElement>(pending.current)
        ?.focus({ preventScroll: true });
      pending.current = null;
    }
  });
  function focusAfterRender(selector: string) {
    pending.current = selector;
  }
  return { root, focusAfterRender };
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
